import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-schema-design-l2-001', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Normalization', question: 'What is Boyce-Codd Normal Form (BCNF)?', options: ['A weaker form of 3NF', 'A stricter version of 3NF where every determinant (left side of a functional dependency) must be a candidate key', 'A form requiring no foreign keys', 'The same as 4NF'], correctAnswer: 1, explanation: 'BCNF strengthens 3NF by requiring that every functional dependency X → Y has X as a superkey. A table can be in 3NF but not BCNF if a non-key column determines part of a candidate key.', tags: ['schema-design', 'normalization', 'bcnf'] },
  { id: 'pg-schema-design-l2-002', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Normalization', question: 'What is a functional dependency?', options: ['A dependency on a function', 'A relationship where the value of one column set uniquely determines the value of another column set (X → Y)', 'A dependency between tables', 'A function that depends on data'], correctAnswer: 1, explanation: 'A functional dependency X → Y means that for any two rows with the same value of X, the value of Y must also be the same. Identifying functional dependencies is essential for normalization.', tags: ['schema-design', 'normalization', 'functional-dependency'] },
  { id: 'pg-schema-design-l2-003', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you create a multi-column CHECK constraint?', options: ['Add CHECK to each column', 'Define a table-level CHECK constraint that references multiple columns in its expression', 'Use multiple single-column CHECKs', 'Multi-column CHECKs are not supported'], correctAnswer: 1, explanation: 'Table-level CHECK constraints can reference any combination of columns in the same row. This is essential for cross-column validations like ensuring end_date > start_date.', codeSnippet: "CREATE TABLE events (\n  id SERIAL PRIMARY KEY,\n  start_date DATE NOT NULL,\n  end_date DATE NOT NULL,\n  min_attendees INTEGER DEFAULT 0,\n  max_attendees INTEGER,\n  CONSTRAINT valid_dates CHECK (end_date >= start_date),\n  CONSTRAINT valid_attendees CHECK (max_attendees >= min_attendees)\n);", tags: ['schema-design', 'check', 'multi-column'] },
  { id: 'pg-schema-design-l2-004', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partial Unique', question: 'What is a partial unique index?', options: ['An index on part of a table', 'A unique index with a WHERE clause that enforces uniqueness only for rows matching the condition', 'An index that is partially built', 'A unique index on a partial column'], correctAnswer: 1, explanation: 'A partial unique index combines a unique constraint with a filter condition. This is useful for conditional uniqueness rules that cannot be expressed with standard UNIQUE constraints.', codeSnippet: "-- Only one active email per user (allow multiple inactive duplicates)\nCREATE UNIQUE INDEX idx_unique_active_email\n  ON users (email)\n  WHERE deleted_at IS NULL;\n\n-- Only one primary phone per customer\nCREATE UNIQUE INDEX idx_unique_primary_phone\n  ON phones (customer_id)\n  WHERE is_primary = true;", tags: ['schema-design', 'partial-index', 'unique', 'conditional'] },
  { id: 'pg-schema-design-l2-005', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Inheritance', question: 'What is table inheritance in PostgreSQL?', options: ['Foreign key relationships', 'A feature where a child table automatically includes all columns of the parent table and queries on the parent include child rows', 'Copying table structures', 'Schema inheritance'], correctAnswer: 1, explanation: 'PostgreSQL table inheritance allows a child table to inherit all columns from a parent. Queries on the parent table automatically include rows from all children. This can model IS-A relationships.', codeSnippet: "CREATE TABLE vehicles (\n  id SERIAL PRIMARY KEY,\n  make TEXT NOT NULL,\n  model TEXT NOT NULL,\n  year INTEGER\n);\n\nCREATE TABLE cars (\n  num_doors INTEGER\n) INHERITS (vehicles);\n\nCREATE TABLE trucks (\n  payload_kg NUMERIC\n) INHERITS (vehicles);", tags: ['schema-design', 'inheritance'] },
  { id: 'pg-schema-design-l2-006', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Inheritance', question: 'What is a major limitation of table inheritance?', options: ['Cannot add columns to child tables', 'UNIQUE constraints, PRIMARY KEY, and FOREIGN KEY constraints are not inherited by child tables and are not enforced across the hierarchy', 'Child tables cannot have indexes', 'Performance is always worse'], correctAnswer: 1, explanation: 'Constraints are not shared across the inheritance hierarchy. A UNIQUE or PRIMARY KEY on the parent only applies to the parent table itself, not to child tables. Foreign keys also do not span the hierarchy.', tags: ['schema-design', 'inheritance', 'limitations'] },
  { id: 'pg-schema-design-l2-007', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'What is table partitioning?', options: ['Splitting a table across databases', 'Dividing a large table into smaller physical pieces (partitions) while maintaining a single logical table for queries', 'Creating multiple copies', 'Vertical splitting of columns'], correctAnswer: 1, explanation: 'Partitioning splits a large table into smaller physical sub-tables based on a partitioning key. PostgreSQL supports range, list, and hash partitioning. Queries automatically route to relevant partitions.', codeSnippet: "CREATE TABLE measurements (\n  id BIGSERIAL,\n  recorded_at TIMESTAMPTZ NOT NULL,\n  value NUMERIC NOT NULL\n) PARTITION BY RANGE (recorded_at);", tags: ['schema-design', 'partitioning'] },
  { id: 'pg-schema-design-l2-008', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'What is range partitioning?', options: ['Partitioning by row range', 'Dividing data based on a continuous range of values in the partition key, such as date ranges or numeric ranges', 'Partitioning by column range', 'A type of query range'], correctAnswer: 1, explanation: 'Range partitioning assigns rows to partitions based on value ranges of the partition key. It is commonly used with dates (monthly/yearly partitions) or sequential IDs.', codeSnippet: "CREATE TABLE measurements (\n  id BIGSERIAL,\n  recorded_at TIMESTAMPTZ NOT NULL,\n  value NUMERIC\n) PARTITION BY RANGE (recorded_at);\n\nCREATE TABLE measurements_2024_q1 PARTITION OF measurements\n  FOR VALUES FROM ('2024-01-01') TO ('2024-04-01');\nCREATE TABLE measurements_2024_q2 PARTITION OF measurements\n  FOR VALUES FROM ('2024-04-01') TO ('2024-07-01');", tags: ['schema-design', 'partitioning', 'range'] },
  { id: 'pg-schema-design-l2-009', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'What is list partitioning?', options: ['Partitioning into linked lists', 'Dividing data based on explicit lists of values in the partition key, such as country codes or status values', 'Creating a list of partitions', 'Partitioning by alphabetical order'], correctAnswer: 1, explanation: 'List partitioning assigns rows to partitions based on explicit value lists. Each partition holds rows matching specific discrete values, useful for categorical data.', codeSnippet: "CREATE TABLE orders (\n  id BIGSERIAL,\n  region TEXT NOT NULL,\n  total NUMERIC\n) PARTITION BY LIST (region);\n\nCREATE TABLE orders_americas PARTITION OF orders\n  FOR VALUES IN ('US', 'CA', 'BR', 'MX');\nCREATE TABLE orders_europe PARTITION OF orders\n  FOR VALUES IN ('DE', 'FR', 'GB', 'ES');", tags: ['schema-design', 'partitioning', 'list'] },
  { id: 'pg-schema-design-l2-010', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'What is hash partitioning?', options: ['Partitioning using hash tables', 'Distributing rows across partitions using a hash of the partition key, ensuring roughly equal distribution', 'Encrypting partition keys', 'Partitioning by hash indexes'], correctAnswer: 1, explanation: 'Hash partitioning computes a hash of the partition key and distributes rows across a specified number of partitions (modulus). This provides even distribution when range or list partitioning is not suitable.', codeSnippet: "CREATE TABLE sessions (\n  id UUID NOT NULL,\n  user_id INTEGER NOT NULL,\n  data JSONB\n) PARTITION BY HASH (id);\n\nCREATE TABLE sessions_p0 PARTITION OF sessions\n  FOR VALUES WITH (MODULUS 4, REMAINDER 0);\nCREATE TABLE sessions_p1 PARTITION OF sessions\n  FOR VALUES WITH (MODULUS 4, REMAINDER 1);\n-- ... p2, p3", tags: ['schema-design', 'partitioning', 'hash'] },
  { id: 'pg-schema-design-l2-011', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Generated Columns', question: 'What is a generated column?', options: ['A column generated by AI', 'A column whose value is automatically computed from an expression involving other columns in the same row', 'A column with auto-increment', 'A randomly generated column'], correctAnswer: 1, explanation: 'Generated columns (PostgreSQL 12+) are computed from expressions on other columns. STORED generated columns are physically stored and updated automatically when source columns change.', codeSnippet: "CREATE TABLE products (\n  id SERIAL PRIMARY KEY,\n  price NUMERIC NOT NULL,\n  tax_rate NUMERIC NOT NULL DEFAULT 0.19,\n  total_price NUMERIC GENERATED ALWAYS AS (price * (1 + tax_rate)) STORED\n);", tags: ['schema-design', 'generated-column'] },
  { id: 'pg-schema-design-l2-012', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Generated Columns', question: 'What types of generated columns does PostgreSQL support?', options: ['STORED and VIRTUAL', 'Only STORED — the computed value is saved on disk; VIRTUAL (computed on read) is not yet supported', 'Only VIRTUAL', 'Neither STORED nor VIRTUAL'], correctAnswer: 1, explanation: 'PostgreSQL currently only supports STORED generated columns, which are computed on write and physically saved. VIRTUAL generated columns (computed on read) are defined in the SQL standard but not yet implemented in PostgreSQL.', codeSnippet: "CREATE TABLE people (\n  first_name TEXT NOT NULL,\n  last_name TEXT NOT NULL,\n  full_name TEXT GENERATED ALWAYS AS\n    (first_name || ' ' || last_name) STORED\n);", tags: ['schema-design', 'generated-column', 'stored'] },
  { id: 'pg-schema-design-l2-013', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Foreign Keys', question: 'How do you create a composite foreign key?', options: ['Use two separate REFERENCES', 'Define a FOREIGN KEY constraint referencing multiple columns that match a composite primary/unique key in the parent table', 'Composite foreign keys are not supported', 'Use an array column'], correctAnswer: 1, explanation: 'A composite foreign key references a multi-column primary or unique key. The number and types of columns must match exactly between the referencing and referenced column sets.', codeSnippet: "CREATE TABLE order_item_notes (\n  id SERIAL PRIMARY KEY,\n  order_id INTEGER NOT NULL,\n  product_id INTEGER NOT NULL,\n  note TEXT NOT NULL,\n  FOREIGN KEY (order_id, product_id)\n    REFERENCES order_items(order_id, product_id)\n);", tags: ['schema-design', 'foreign-key', 'composite'] },
  { id: 'pg-schema-design-l2-014', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you make a constraint deferrable?', options: ['Use ALTER CONSTRAINT DEFER', 'Add DEFERRABLE to the constraint definition, optionally with INITIALLY DEFERRED or INITIALLY IMMEDIATE', 'Use SET CONSTRAINTS DEFERRED', 'All constraints are deferrable by default'], correctAnswer: 1, explanation: 'The DEFERRABLE keyword makes a constraint eligible for deferral. INITIALLY DEFERRED means it is deferred by default; INITIALLY IMMEDIATE means it is checked immediately but can be deferred per transaction.', codeSnippet: "CREATE TABLE tree_nodes (\n  id SERIAL PRIMARY KEY,\n  parent_id INTEGER REFERENCES tree_nodes(id)\n    DEFERRABLE INITIALLY DEFERRED,\n  sort_order INTEGER UNIQUE DEFERRABLE INITIALLY IMMEDIATE\n);\n\n-- Defer within a transaction:\nSET CONSTRAINTS ALL DEFERRED;", tags: ['schema-design', 'constraints', 'deferrable'] },
  { id: 'pg-schema-design-l2-015', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'EAV Pattern', question: 'What is the Entity-Attribute-Value (EAV) pattern?', options: ['A normalization form', 'A schema design that stores each attribute as a row with entity_id, attribute_name, and value columns instead of dedicated columns', 'A type of join pattern', 'An indexing strategy'], correctAnswer: 1, explanation: 'EAV stores data as key-value pairs: (entity_id, attribute_name, attribute_value). While flexible for dynamic attributes, it has many drawbacks: poor type safety, difficult queries, and no constraint enforcement.', codeSnippet: "-- EAV pattern (generally discouraged):\nCREATE TABLE entity_attributes (\n  entity_id INTEGER REFERENCES entities(id),\n  attribute_name TEXT NOT NULL,\n  attribute_value TEXT,\n  PRIMARY KEY (entity_id, attribute_name)\n);\n\n-- Better alternative: use JSONB\nCREATE TABLE entities (\n  id SERIAL PRIMARY KEY,\n  attributes JSONB DEFAULT '{}'\n);", tags: ['schema-design', 'eav', 'anti-pattern'] },
  { id: 'pg-schema-design-l2-016', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Polymorphic Associations', question: 'What is the polymorphic association anti-pattern?', options: ['Using polymorphic types', 'Storing a reference_id and reference_type to point to different tables, bypassing foreign key constraints', 'Using multiple inheritance', 'Creating many-to-many relationships'], correctAnswer: 1, explanation: 'Polymorphic associations use a type column and a generic ID column to reference different tables. This prevents using foreign keys for referential integrity. Better alternatives include separate FK columns or shared parent tables.', codeSnippet: "-- Anti-pattern:\nCREATE TABLE comments (\n  id SERIAL PRIMARY KEY,\n  commentable_type TEXT,  -- 'post', 'photo', 'video'\n  commentable_id INTEGER, -- no FK possible!\n  body TEXT\n);\n\n-- Better: separate FKs or inheritance\nCREATE TABLE comments (\n  id SERIAL PRIMARY KEY,\n  post_id INTEGER REFERENCES posts(id),\n  photo_id INTEGER REFERENCES photos(id),\n  body TEXT,\n  CHECK (num_nonnulls(post_id, photo_id) = 1)\n);", tags: ['schema-design', 'polymorphic', 'anti-pattern'] },
  { id: 'pg-schema-design-l2-017', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Audit Trail', question: 'How do you design an audit trail for tracking changes?', options: ['Use database logs only', 'Create an audit table that records who changed what, when, and the old/new values, typically populated by triggers', 'Use version control', 'Enable query logging'], correctAnswer: 1, explanation: 'An audit trail table stores the timestamp, user, operation type, table name, and old/new values for each change. Triggers on the tracked tables automatically populate the audit table.', codeSnippet: "CREATE TABLE audit_log (\n  id BIGSERIAL PRIMARY KEY,\n  table_name TEXT NOT NULL,\n  operation TEXT NOT NULL,  -- INSERT, UPDATE, DELETE\n  row_id INTEGER NOT NULL,\n  old_values JSONB,\n  new_values JSONB,\n  changed_by TEXT DEFAULT current_user,\n  changed_at TIMESTAMPTZ DEFAULT NOW()\n);", tags: ['schema-design', 'audit-trail', 'triggers'] },
  { id: 'pg-schema-design-l2-018', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'What does the EXCLUDE constraint using GiST do?', options: ['Excludes rows from queries', 'Ensures that for any two rows, at least one of the specified comparisons returns false, using GiST index operators', 'Excludes columns from indexes', 'Excludes partitions from queries'], correctAnswer: 1, explanation: 'EXCLUDE USING GiST is powerful for range and spatial constraints. It generalizes UNIQUE by allowing operators other than equality, such as && for range overlap detection.', codeSnippet: "CREATE EXTENSION btree_gist;\n\nCREATE TABLE room_bookings (\n  room_id INTEGER NOT NULL,\n  during TSTZRANGE NOT NULL,\n  EXCLUDE USING GIST (\n    room_id WITH =,\n    during WITH &&\n  )\n);\n-- Prevents overlapping bookings for the same room", tags: ['schema-design', 'exclusion-constraint', 'gist'] },
  { id: 'pg-schema-design-l2-019', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Materialized Views', question: 'What is a materialized view?', options: ['A view that is always up to date', 'A view that stores query results physically on disk, providing fast reads but requiring explicit refresh to update', 'A view with material design styling', 'A temporary view'], correctAnswer: 1, explanation: 'Materialized views cache the results of a query on disk. Unlike regular views, they are not automatically updated. You must run REFRESH MATERIALIZED VIEW to update the cached data.', codeSnippet: "CREATE MATERIALIZED VIEW monthly_sales AS\n  SELECT date_trunc('month', order_date) AS month,\n    SUM(total) AS revenue,\n    COUNT(*) AS order_count\n  FROM orders\n  GROUP BY 1;\n\n-- Refresh when needed:\nREFRESH MATERIALIZED VIEW monthly_sales;", tags: ['schema-design', 'materialized-view'] },
  { id: 'pg-schema-design-l2-020', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Materialized Views', question: 'How do you refresh a materialized view without blocking reads?', options: ['Use REFRESH MATERIALIZED VIEW CONCURRENTLY — requires a unique index on the view', 'Materialized views always block during refresh', 'Use REFRESH ASYNC', 'Drop and recreate the view'], correctAnswer: 0, explanation: 'REFRESH MATERIALIZED VIEW CONCURRENTLY builds the new data alongside the old, then swaps them atomically. This requires at least one unique index on the materialized view. Reads are not blocked during refresh.', codeSnippet: "CREATE UNIQUE INDEX ON monthly_sales (month);\n\nREFRESH MATERIALIZED VIEW CONCURRENTLY monthly_sales;\n-- Reads continue working during refresh", tags: ['schema-design', 'materialized-view', 'concurrent-refresh'] },
  { id: 'pg-schema-design-l2-021', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'What is partition pruning?', options: ['Removing old partitions', 'The query optimizer skipping irrelevant partitions based on the WHERE clause, scanning only partitions that might contain matching rows', 'Cleaning partition metadata', 'Compressing partition data'], correctAnswer: 1, explanation: 'Partition pruning is an optimization where the planner excludes partitions that cannot contain rows matching the query filter. This significantly reduces I/O for queries with selective WHERE clauses on the partition key.', codeSnippet: "-- With monthly partitions on order_date:\nEXPLAIN SELECT * FROM orders WHERE order_date = '2024-03-15';\n-- Only scans the March 2024 partition, skips all others", tags: ['schema-design', 'partitioning', 'pruning', 'optimization'] },
  { id: 'pg-schema-design-l2-022', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Multi-tenancy', question: 'What are common approaches for multi-tenant database design?', options: ['Always use separate databases', 'Three approaches: shared table with tenant_id column, separate schemas per tenant, or separate databases per tenant', 'Always use one table', 'Use row-level security only'], correctAnswer: 1, explanation: 'Multi-tenancy can be implemented at three levels: shared tables (add tenant_id, simplest), separate schemas (better isolation), or separate databases (maximum isolation). Each has trade-offs in complexity, isolation, and resource usage.', codeSnippet: "-- Approach 1: Shared table with tenant_id\nCREATE TABLE orders (\n  id SERIAL PRIMARY KEY,\n  tenant_id INTEGER NOT NULL REFERENCES tenants(id),\n  total NUMERIC\n);\nCREATE INDEX ON orders (tenant_id);\n\n-- Approach 2: Row-level security\nALTER TABLE orders ENABLE ROW LEVEL SECURITY;\nCREATE POLICY tenant_isolation ON orders\n  USING (tenant_id = current_setting('app.tenant_id')::int);", tags: ['schema-design', 'multi-tenancy', 'patterns'] },
  { id: 'pg-schema-design-l2-023', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'What is NOT VALID when adding a constraint?', options: ['The constraint is invalid', 'The constraint is added without checking existing rows, only enforced on future changes — validates faster on large tables', 'The constraint cannot be used', 'The constraint is temporary'], correctAnswer: 1, explanation: 'Adding a constraint with NOT VALID skips validation of existing data, making the ALTER TABLE much faster. The constraint still applies to new/updated rows. Use VALIDATE CONSTRAINT later to check existing data without blocking writes.', codeSnippet: "-- Fast: don't check existing rows\nALTER TABLE orders ADD CONSTRAINT positive_total\n  CHECK (total > 0) NOT VALID;\n\n-- Later, validate existing data (weaker lock):\nALTER TABLE orders VALIDATE CONSTRAINT positive_total;", tags: ['schema-design', 'constraints', 'not-valid'] },
  { id: 'pg-schema-design-l2-024', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Inheritance', question: 'How do you query only the parent table without child rows?', options: ['Use WHERE NOT inherited', 'Use ONLY keyword: SELECT * FROM ONLY parent_table', 'Child rows are never included', 'Use a subquery to exclude children'], correctAnswer: 1, explanation: 'The ONLY keyword restricts a query to the specified table only, excluding rows from child (inherited) tables. Without ONLY, queries on a parent table include all rows from the inheritance hierarchy.', codeSnippet: "-- Include all children (default):\nSELECT * FROM vehicles;\n\n-- Only the parent table:\nSELECT * FROM ONLY vehicles;\n\n-- Also works with UPDATE and DELETE:\nDELETE FROM ONLY vehicles WHERE id = 1;", tags: ['schema-design', 'inheritance', 'only-keyword'] },
  { id: 'pg-schema-design-l2-025', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Row Level Security', question: 'What is Row Level Security (RLS)?', options: ['Encrypting individual rows', 'A feature that restricts which rows a user can see or modify based on security policies defined on the table', 'Row-level locking', 'Securing rows with passwords'], correctAnswer: 1, explanation: 'RLS adds transparent WHERE-clause filters to all queries on a table based on the current user or session variables. Policies define which rows each user can SELECT, INSERT, UPDATE, or DELETE.', codeSnippet: "ALTER TABLE documents ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY user_documents ON documents\n  USING (owner_id = current_setting('app.user_id')::int)\n  WITH CHECK (owner_id = current_setting('app.user_id')::int);", tags: ['schema-design', 'rls', 'security'] },
  { id: 'pg-schema-design-l2-026', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Row Level Security', question: 'What is the difference between USING and WITH CHECK in an RLS policy?', options: ['They are identical', 'USING filters rows for SELECT/UPDATE/DELETE visibility; WITH CHECK validates new or modified rows for INSERT/UPDATE', 'USING is for reads, WITH CHECK is for connections', 'USING is required, WITH CHECK is optional'], correctAnswer: 1, explanation: 'The USING expression acts as a filter for existing rows (what you can see/modify). WITH CHECK validates new data (what you can write). For UPDATE, USING filters which rows can be updated, and WITH CHECK validates the new values.', codeSnippet: "-- Users can see their own data and public data,\n-- but can only create/modify their own data\nCREATE POLICY data_policy ON items\n  USING (owner_id = current_user_id() OR is_public = true)\n  WITH CHECK (owner_id = current_user_id());", tags: ['schema-design', 'rls', 'using-vs-with-check'] },
  { id: 'pg-schema-design-l2-027', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'What is a default partition?', options: ['The first partition created', 'A partition that catches all rows that do not match any other partition\'s bounds', 'The largest partition', 'A partition with default values'], correctAnswer: 1, explanation: 'A default partition receives rows that do not fit into any defined partition. Without a default partition, inserting such rows causes an error. It acts as a catch-all.', codeSnippet: "CREATE TABLE orders (\n  id SERIAL, region TEXT NOT NULL, total NUMERIC\n) PARTITION BY LIST (region);\n\nCREATE TABLE orders_us PARTITION OF orders FOR VALUES IN ('US');\nCREATE TABLE orders_eu PARTITION OF orders FOR VALUES IN ('EU');\nCREATE TABLE orders_other PARTITION OF orders DEFAULT;", tags: ['schema-design', 'partitioning', 'default-partition'] },
  { id: 'pg-schema-design-l2-028', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'How does num_nonnulls() help with constraint design?', options: ['It counts columns', 'It returns the count of non-NULL arguments, enabling constraints like exactly one of several nullable FK columns must be set', 'It validates NOT NULL constraints', 'It normalizes null values'], correctAnswer: 1, explanation: 'num_nonnulls() counts how many of its arguments are not NULL. Combined with CHECK constraints, it enables exactly-one-of-N or at-most-one-of-N patterns for mutually exclusive nullable columns.', codeSnippet: "CREATE TABLE notifications (\n  id SERIAL PRIMARY KEY,\n  email_id INTEGER REFERENCES emails(id),\n  sms_id INTEGER REFERENCES sms_messages(id),\n  push_id INTEGER REFERENCES push_messages(id),\n  -- Exactly one delivery method must be set:\n  CHECK (num_nonnulls(email_id, sms_id, push_id) = 1)\n);", tags: ['schema-design', 'constraints', 'num-nonnulls'] },
  { id: 'pg-schema-design-l2-029', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Temporal Design', question: 'How do you design a table that tracks historical changes (temporal data)?', options: ['Use a log file', 'Add valid_from and valid_to columns with range types and constraints to create a temporal (bi-temporal) table', 'Use database replication', 'Store each version as a JSON blob'], correctAnswer: 1, explanation: 'Temporal tables track the validity period of each row. Using TSTZRANGE columns with exclusion constraints ensures no overlapping validity periods for the same entity.', codeSnippet: "CREATE TABLE employee_salaries (\n  employee_id INTEGER NOT NULL,\n  salary NUMERIC NOT NULL,\n  valid_during TSTZRANGE NOT NULL DEFAULT tstzrange(NOW(), NULL),\n  EXCLUDE USING GIST (\n    employee_id WITH =,\n    valid_during WITH &&\n  )\n);", tags: ['schema-design', 'temporal', 'history'] },
  { id: 'pg-schema-design-l2-030', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'Can you create indexes on partitioned tables?', options: ['No, partitions cannot have indexes', 'Yes, creating an index on the parent table automatically creates matching indexes on all existing and future partitions', 'Only on individual partitions', 'Only unique indexes'], correctAnswer: 1, explanation: 'Since PostgreSQL 11, creating an index on a partitioned table automatically creates corresponding indexes on all current partitions. New partitions added later also get the index automatically.', codeSnippet: "-- Creates index on all partitions:\nCREATE INDEX ON measurements (value);\n\n-- Unique indexes must include the partition key:\nCREATE UNIQUE INDEX ON measurements (id, recorded_at);", tags: ['schema-design', 'partitioning', 'indexes'] },
  { id: 'pg-schema-design-l2-031', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Foreign Keys', question: 'What is ON DELETE SET DEFAULT?', options: ['Sets the column to its DEFAULT value when the referenced row is deleted', 'Sets the foreign key to the default table', 'Restores the original value', 'Sets all columns to defaults'], correctAnswer: 0, explanation: 'ON DELETE SET DEFAULT sets the foreign key column to its DEFAULT value when the referenced parent row is deleted. The default value must exist in the referenced table, or the operation fails.', codeSnippet: "CREATE TABLE tasks (\n  id SERIAL PRIMARY KEY,\n  category_id INTEGER DEFAULT 1\n    REFERENCES categories(id) ON DELETE SET DEFAULT,\n  title TEXT NOT NULL\n);\n-- Deleting a category moves its tasks to category 1 (e.g., 'Uncategorized')", tags: ['schema-design', 'foreign-key', 'on-delete-set-default'] },
  { id: 'pg-schema-design-l2-032', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Generated Columns', question: 'Can a generated column reference other generated columns?', options: ['Yes, in any order', 'No, a generated column can only reference base (non-generated) columns of the same table', 'Only if they are defined first', 'Only VIRTUAL generated columns can'], correctAnswer: 1, explanation: 'Generated columns can only reference non-generated columns. This prevents circular dependencies and simplifies the computation order. If you need to chain computations, use a trigger instead.', tags: ['schema-design', 'generated-column', 'limitations'] },
  { id: 'pg-schema-design-l2-033', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Normalization', question: 'What is a transitive dependency?', options: ['A dependency that transits between databases', 'When column C depends on column B, and B depends on column A (the primary key), so C indirectly depends on A through B', 'A dependency that changes over time', 'A foreign key chain'], correctAnswer: 1, explanation: 'A transitive dependency occurs when a non-key column depends on another non-key column. For example, if zip_code → city and employee_id → zip_code, then city transitively depends on employee_id. 3NF eliminates these.', codeSnippet: "-- Transitive dependency: city depends on zip_code, not directly on employee_id\n-- Violates 3NF:\nCREATE TABLE employees (id INT PK, name TEXT, zip_code TEXT, city TEXT);\n\n-- Fixed (3NF):\nCREATE TABLE employees (id INT PK, name TEXT, zip_code TEXT REFERENCES zip_codes);\nCREATE TABLE zip_codes (zip_code TEXT PK, city TEXT);", tags: ['schema-design', 'normalization', 'transitive-dependency'] },
  { id: 'pg-schema-design-l2-034', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you create a unique constraint that ignores NULL values?', options: ['UNIQUE NULLS NOT DISTINCT (PostgreSQL 15+) treats NULLs as equal; standard UNIQUE allows multiple NULLs', 'Use UNIQUE IGNORE NULLS', 'All UNIQUE constraints ignore NULLs', 'Use a partial index WHERE col IS NOT NULL'], correctAnswer: 0, explanation: 'By default, UNIQUE treats NULLs as distinct (multiple NULLs allowed). PostgreSQL 15 added NULLS NOT DISTINCT to treat NULLs as equal. Before PG15, use a partial unique index filtering out NULLs.', codeSnippet: "-- PostgreSQL 15+:\nCREATE TABLE t (\n  id SERIAL PRIMARY KEY,\n  code TEXT UNIQUE NULLS NOT DISTINCT  -- only one NULL allowed\n);\n\n-- Before PG15: partial unique index\nCREATE UNIQUE INDEX ON t (code) WHERE code IS NOT NULL;", tags: ['schema-design', 'unique', 'nulls', 'pg15'] },
  { id: 'pg-schema-design-l2-035', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Schemas', question: 'How do you grant access to all tables in a schema?', options: ['GRANT ALL ON SCHEMA', 'Use GRANT ... ON ALL TABLES IN SCHEMA and ALTER DEFAULT PRIVILEGES for future tables', 'GRANT SELECT ON *', 'Schemas automatically grant access'], correctAnswer: 1, explanation: 'GRANT ... ON ALL TABLES IN SCHEMA affects existing tables. ALTER DEFAULT PRIVILEGES sets permissions for future objects. Both are needed for complete access management.', codeSnippet: "-- Grant on existing tables:\nGRANT SELECT ON ALL TABLES IN SCHEMA analytics TO reader_role;\n\n-- Grant on future tables:\nALTER DEFAULT PRIVILEGES IN SCHEMA analytics\n  GRANT SELECT ON TABLES TO reader_role;", tags: ['schema-design', 'schemas', 'grants', 'permissions'] },
  { id: 'pg-schema-design-l2-036', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'What is sub-partitioning (multi-level partitioning)?', options: ['Partitioning a partition further', 'Dividing an already-partitioned table into additional levels — e.g., first by range, then by list within each range partition', 'Partitioning twice for redundancy', 'Creating sub-tables'], correctAnswer: 1, explanation: 'PostgreSQL supports multi-level partitioning where a partition itself is partitioned. For example, you could partition by year (range), then by region (list) within each year.', codeSnippet: "CREATE TABLE sales (\n  id BIGSERIAL, region TEXT, sale_date DATE, amount NUMERIC\n) PARTITION BY RANGE (sale_date);\n\nCREATE TABLE sales_2024 PARTITION OF sales\n  FOR VALUES FROM ('2024-01-01') TO ('2025-01-01')\n  PARTITION BY LIST (region);\n\nCREATE TABLE sales_2024_us PARTITION OF sales_2024\n  FOR VALUES IN ('US');", tags: ['schema-design', 'partitioning', 'sub-partitioning'] },
  { id: 'pg-schema-design-l2-037', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Tree Structures', question: 'What is the adjacency list pattern for hierarchical data?', options: ['A linked list in SQL', 'Each row stores a reference to its parent via a parent_id foreign key — simple to implement but requires recursive queries for tree traversal', 'A list of adjacent tables', 'A spatial data structure'], correctAnswer: 1, explanation: 'The adjacency list is the simplest hierarchical pattern: each row has a parent_id pointing to its parent. While easy to implement, querying ancestors or descendants requires recursive CTEs.', codeSnippet: "CREATE TABLE categories (\n  id SERIAL PRIMARY KEY,\n  name TEXT NOT NULL,\n  parent_id INTEGER REFERENCES categories(id)\n);\n\n-- Get full tree using recursive CTE:\nWITH RECURSIVE tree AS (\n  SELECT id, name, parent_id, 0 AS depth FROM categories WHERE parent_id IS NULL\n  UNION ALL\n  SELECT c.id, c.name, c.parent_id, t.depth + 1\n  FROM categories c JOIN tree t ON c.parent_id = t.id\n)\nSELECT * FROM tree;", tags: ['schema-design', 'hierarchy', 'adjacency-list'] },
  { id: 'pg-schema-design-l2-038', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Tree Structures', question: 'What is the materialized path pattern for hierarchical data?', options: ['A physical file path', 'Each row stores the full path from root to itself as a string (e.g., "1/3/7/"), enabling ancestor/descendant queries with LIKE', 'A path through indexes', 'A reference to a materialized view'], correctAnswer: 1, explanation: 'The materialized path stores the complete ancestry path in each row. This enables efficient ancestor/descendant queries using LIKE or the ltree extension, at the cost of update complexity when nodes move.', codeSnippet: "CREATE TABLE categories (\n  id SERIAL PRIMARY KEY,\n  name TEXT NOT NULL,\n  path TEXT NOT NULL  -- e.g., '1.3.7'\n);\n\n-- Find all descendants of node 3:\nSELECT * FROM categories WHERE path LIKE '%.3.%';\n\n-- Better: use ltree extension\nCREATE EXTENSION ltree;\nALTER TABLE categories ADD COLUMN ltree_path ltree;\nSELECT * FROM categories WHERE ltree_path <@ '1.3';", tags: ['schema-design', 'hierarchy', 'materialized-path', 'ltree'] },
  { id: 'pg-schema-design-l2-039', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'What does adding a foreign key with NOT VALID do?', options: ['Creates an invalid constraint', 'Adds the FK constraint for future changes only, without locking the table to verify existing rows — validate later with VALIDATE CONSTRAINT', 'Creates a foreign key that allows violations', 'Marks the constraint as pending'], correctAnswer: 1, explanation: 'NOT VALID on a foreign key skips the scan of existing rows, avoiding long locks on large tables. The constraint applies to new inserts/updates. Run VALIDATE CONSTRAINT later to check existing data with a weaker lock.', codeSnippet: "-- Fast: no table scan needed (ShareRowExclusiveLock only briefly)\nALTER TABLE orders ADD CONSTRAINT fk_customer\n  FOREIGN KEY (customer_id) REFERENCES customers(id)\n  NOT VALID;\n\n-- Later: validate with ShareUpdateExclusiveLock (allows reads/writes)\nALTER TABLE orders VALIDATE CONSTRAINT fk_customer;", tags: ['schema-design', 'foreign-key', 'not-valid', 'online-migration'] },
  { id: 'pg-schema-design-l2-040', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Naming', question: 'What is a good naming convention for foreign key columns?', options: ['Use the same name as the referenced table', 'Use referenced_table_singular_id (e.g., user_id for a reference to users.id) — consistently indicates the relationship', 'Use fk_ prefix always', 'Any name works equally well'], correctAnswer: 1, explanation: 'Naming FK columns as {referenced_table_singular}_{referenced_column} (e.g., user_id, order_id) makes relationships immediately obvious. This convention enables tools and ORMs to auto-detect relationships.', codeSnippet: "CREATE TABLE orders (\n  id SERIAL PRIMARY KEY,\n  customer_id INTEGER REFERENCES customers(id),  -- clear naming\n  shipping_address_id INTEGER REFERENCES addresses(id),\n  billing_address_id INTEGER REFERENCES addresses(id)\n);", tags: ['schema-design', 'naming', 'foreign-key'] },
  { id: 'pg-schema-design-l2-041', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'How do you attach an existing table as a partition?', options: ['Use ALTER TABLE ... ATTACH PARTITION specifying the partition bounds', 'Move data using INSERT INTO ... SELECT', 'Use CREATE PARTITION FROM TABLE', 'Use MERGE TABLE'], correctAnswer: 0, explanation: 'ALTER TABLE parent ATTACH PARTITION child FOR VALUES ... converts an existing table into a partition. PostgreSQL validates that all rows satisfy the partition constraint (use a CHECK constraint on the child first to skip the scan).', codeSnippet: "-- Add matching check constraint first (to skip scan on attach):\nALTER TABLE measurements_2024_q1\n  ADD CONSTRAINT partition_check\n  CHECK (recorded_at >= '2024-01-01' AND recorded_at < '2024-04-01');\n\n-- Then attach:\nALTER TABLE measurements\n  ATTACH PARTITION measurements_2024_q1\n  FOR VALUES FROM ('2024-01-01') TO ('2024-04-01');", tags: ['schema-design', 'partitioning', 'attach'] },
  { id: 'pg-schema-design-l2-042', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'How do you detach a partition from a partitioned table?', options: ['DROP PARTITION', 'ALTER TABLE parent DETACH PARTITION child — the partition becomes a standalone table', 'DELETE PARTITION', 'REMOVE PARTITION'], correctAnswer: 1, explanation: 'ALTER TABLE ... DETACH PARTITION converts a partition back into a regular standalone table. Use CONCURRENTLY (PostgreSQL 14+) to avoid blocking queries during detach.', codeSnippet: "-- Detach (blocks queries briefly):\nALTER TABLE measurements DETACH PARTITION measurements_2023_q1;\n\n-- Detach concurrently (PG 14+, no blocking):\nALTER TABLE measurements\n  DETACH PARTITION measurements_2023_q1 CONCURRENTLY;", tags: ['schema-design', 'partitioning', 'detach'] },
  { id: 'pg-schema-design-l2-043', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Generated Columns', question: 'Can you create an index on a generated column?', options: ['No, generated columns cannot be indexed', 'Yes, generated columns can be indexed just like regular columns since STORED columns have physical data', 'Only with expression indexes', 'Only GIN indexes'], correctAnswer: 1, explanation: 'STORED generated columns contain physical data on disk, so they can be indexed like any other column. This is useful for optimizing queries that filter or sort by computed values.', codeSnippet: "CREATE TABLE products (\n  price NUMERIC NOT NULL,\n  tax_rate NUMERIC NOT NULL DEFAULT 0.19,\n  total NUMERIC GENERATED ALWAYS AS (price * (1 + tax_rate)) STORED\n);\n\nCREATE INDEX ON products (total);  -- index on generated column", tags: ['schema-design', 'generated-column', 'index'] },
  { id: 'pg-schema-design-l2-044', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Normalization', question: 'What is Fourth Normal Form (4NF)?', options: ['Having four tables', 'Being in BCNF and having no multi-valued dependencies — independent multi-valued facts must be in separate tables', 'Having four columns', 'A form for time-series data'], correctAnswer: 1, explanation: '4NF eliminates multi-valued dependencies. If a table has two or more independent multi-valued facts about an entity, they should be stored in separate tables to avoid combinatorial explosion of rows.', codeSnippet: "-- Violates 4NF: languages and skills are independent\nCREATE TABLE person_attrs (person_id INT, language TEXT, skill TEXT);\n-- person_id=1 speaks EN,DE and knows SQL,Python\n-- Must store: (1,EN,SQL),(1,EN,Python),(1,DE,SQL),(1,DE,Python)\n\n-- Fixed (4NF):\nCREATE TABLE person_languages (person_id INT, language TEXT);\nCREATE TABLE person_skills (person_id INT, skill TEXT);", tags: ['schema-design', 'normalization', '4nf'] },
  { id: 'pg-schema-design-l2-045', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Views', question: 'What does WITH CHECK OPTION do on a view?', options: ['Adds a CHECK constraint', 'Prevents INSERT/UPDATE through the view if the new row would not be visible through the view\'s WHERE clause', 'Checks view permissions', 'Validates the view query'], correctAnswer: 1, explanation: 'WITH CHECK OPTION ensures that data modifications through the view do not produce rows that would be excluded by the view\'s WHERE clause. LOCAL checks only the current view; CASCADED checks all underlying views.', codeSnippet: "CREATE VIEW active_users AS\n  SELECT * FROM users WHERE status = 'active'\n  WITH CHECK OPTION;\n\n-- This fails:\nINSERT INTO active_users (name, status) VALUES ('Bob', 'inactive');\n-- ERROR: new row violates check option for view \"active_users\"", tags: ['schema-design', 'views', 'check-option'] },
  { id: 'pg-schema-design-l2-046', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Row Level Security', question: 'How do you bypass RLS for a specific role?', options: ['Disable RLS globally', 'Grant the BYPASSRLS attribute to the role, or use ALTER TABLE ... FORCE ROW LEVEL SECURITY for table owners', 'Use WITH NO RLS hint', 'RLS cannot be bypassed'], correctAnswer: 1, explanation: 'Table owners bypass RLS by default (unless FORCE ROW LEVEL SECURITY is set). The BYPASSRLS role attribute allows any role to bypass all RLS policies. Superusers always bypass RLS.', codeSnippet: "-- Table owners bypass RLS unless forced:\nALTER TABLE sensitive_data FORCE ROW LEVEL SECURITY;\n\n-- Grant bypass to admin role:\nALTER ROLE admin_user BYPASSRLS;", tags: ['schema-design', 'rls', 'bypass'] },
  { id: 'pg-schema-design-l2-047', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Inheritance', question: 'How does modern PostgreSQL partitioning compare to table inheritance?', options: ['They are identical', 'Partitioning is declarative with automatic row routing, constraint enforcement, and pruning — preferred over inheritance for data division', 'Inheritance is always better', 'Partitioning replaces inheritance entirely'], correctAnswer: 1, explanation: 'Declarative partitioning (PG 10+) handles row routing, constraint exclusion, and pruning automatically. Inheritance requires triggers for routing and lacks partition pruning. Use partitioning for data division and inheritance only for IS-A modeling.', tags: ['schema-design', 'partitioning', 'inheritance', 'comparison'] },
  { id: 'pg-schema-design-l2-048', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you ensure a column value exists in a set without a foreign key?', options: ['Use a separate lookup table', 'Use a CHECK constraint with an IN list or create an enum type', 'Use a trigger', 'Values cannot be constrained without FK'], correctAnswer: 1, explanation: 'For small, static value sets, a CHECK(col IN (...)) or enum type works well. For larger or dynamic sets, a lookup/reference table with a foreign key is better.', codeSnippet: "-- Using CHECK:\nCREATE TABLE tasks (\n  id SERIAL PRIMARY KEY,\n  status TEXT CHECK (status IN ('pending', 'active', 'completed', 'cancelled'))\n);\n\n-- Using enum (better for reuse):\nCREATE TYPE task_status AS ENUM ('pending', 'active', 'completed', 'cancelled');\nCREATE TABLE tasks (\n  id SERIAL PRIMARY KEY,\n  status task_status NOT NULL DEFAULT 'pending'\n);", tags: ['schema-design', 'constraints', 'check-in', 'enum'] },
  { id: 'pg-schema-design-l2-049', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Migration', question: 'What is a safe approach to adding a NOT NULL constraint on a large table?', options: ['Just add NOT NULL directly', 'Add a CHECK (col IS NOT NULL) NOT VALID first (lightweight lock), then VALIDATE CONSTRAINT (no exclusive lock), then SET NOT NULL (instant since constraint exists)', 'Use a maintenance window', 'It always requires downtime'], correctAnswer: 1, explanation: 'Adding NOT NULL directly scans the entire table with an exclusive lock. The safe approach: add a CHECK NOT VALID, validate it separately, then PostgreSQL recognizes the existing valid CHECK and adds NOT NULL without a full scan.', codeSnippet: "-- Step 1: Add check constraint without scanning (fast)\nALTER TABLE orders ADD CONSTRAINT orders_email_nn\n  CHECK (email IS NOT NULL) NOT VALID;\n\n-- Step 2: Validate (allows concurrent reads/writes)\nALTER TABLE orders VALIDATE CONSTRAINT orders_email_nn;\n\n-- Step 3: Set NOT NULL (instant, PG recognizes the CHECK)\nALTER TABLE orders ALTER COLUMN email SET NOT NULL;\nALTER TABLE orders DROP CONSTRAINT orders_email_nn;", tags: ['schema-design', 'migration', 'not-null', 'zero-downtime'] },
  { id: 'pg-schema-design-l2-050', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Normalization', question: 'When is denormalization justified?', options: ['Always for better performance', 'When read performance is critical and the cost of maintaining redundant data through triggers or application logic is acceptable', 'Never, it breaks data integrity', 'Only for temporary tables'], correctAnswer: 1, explanation: 'Denormalization is justified when read-heavy workloads benefit from avoiding complex joins, and the team is prepared to manage data consistency through triggers, materialized views, or application logic.', tags: ['schema-design', 'denormalization', 'trade-offs'] },
  { id: 'pg-schema-design-l2-051', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Data Types', question: 'When should you use a range type instead of separate start/end columns?', options: ['Never, separate columns are always better', 'When you need to enforce non-overlapping constraints, perform containment checks, or use range-specific operators and indexes', 'Only for date ranges', 'Range types are deprecated'], correctAnswer: 1, explanation: 'Range types (int4range, tstzrange, daterange, etc.) provide built-in operators for overlap (&&), containment (@>), and adjacency (-|-). They enable EXCLUDE constraints and GiST indexing that separate columns cannot.', codeSnippet: "-- Instead of start_time and end_time columns:\nCREATE TABLE bookings (\n  id SERIAL PRIMARY KEY,\n  room_id INTEGER NOT NULL,\n  during TSTZRANGE NOT NULL,\n  EXCLUDE USING GIST (room_id WITH =, during WITH &&)\n);\n\n-- Containment check:\nSELECT * FROM bookings WHERE during @> NOW();", tags: ['schema-design', 'range-types', 'data-types'] },
  { id: 'pg-schema-design-l2-052', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Migration', question: 'How do you safely add a column with a DEFAULT value on a large table?', options: ['It is always instant since PostgreSQL 11', 'PostgreSQL 11+ makes adding a column with a constant DEFAULT instant (no rewrite), but volatile defaults or generated columns still rewrite', 'Use a temporary table', 'It always requires a table rewrite'], correctAnswer: 1, explanation: 'Since PostgreSQL 11, adding a column with a constant/immutable DEFAULT is a metadata-only operation (instant). The default is stored in pg_attribute and filled in on read. Volatile expressions like NOW() still require a rewrite.', codeSnippet: "-- Instant (PG 11+, constant default):\nALTER TABLE large_table ADD COLUMN status TEXT DEFAULT 'active';\n\n-- Still requires rewrite (volatile default):\nALTER TABLE large_table ADD COLUMN created_at TIMESTAMPTZ DEFAULT NOW();\n-- Workaround: add without default, then backfill in batches", tags: ['schema-design', 'migration', 'add-column', 'performance'] },
  { id: 'pg-schema-design-l2-053', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Views', question: 'What is a security barrier view?', options: ['A view with a firewall', 'A view with security_barrier = true that prevents optimizer from pushing user conditions below the view\'s WHERE, preventing data leaks via side-channel functions', 'A view requiring authentication', 'An encrypted view'], correctAnswer: 1, explanation: 'Security barrier views prevent the optimizer from reordering conditions in ways that could leak data. Without this, a user-supplied function in WHERE could be evaluated on rows the view should hide.', codeSnippet: "CREATE VIEW public_users WITH (security_barrier = true) AS\n  SELECT id, name, email\n  FROM users\n  WHERE is_public = true;\n\n-- Prevents: SELECT * FROM public_users WHERE leak_function(secret_col)", tags: ['schema-design', 'views', 'security-barrier'] },
  { id: 'pg-schema-design-l2-054', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'What are the main benefits of partitioning?', options: ['Only reduces storage', 'Improved query performance via partition pruning, faster bulk deletes by dropping partitions, and easier maintenance (VACUUM, backup per partition)', 'Only helps with writes', 'Only organizational benefits'], correctAnswer: 1, explanation: 'Partitioning benefits: (1) Queries scan only relevant partitions (pruning), (2) Dropping a partition is instant vs. deleting millions of rows, (3) VACUUM and maintenance can target individual partitions, (4) Partitions can have different tablespaces.', tags: ['schema-design', 'partitioning', 'benefits'] },
  { id: 'pg-schema-design-l2-055', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Tree Structures', question: 'What is the closure table pattern for hierarchical data?', options: ['A table that closes relationships', 'A separate table storing all ancestor-descendant pairs, enabling efficient queries for any tree relationship without recursion', 'A table with closed constraints', 'A finalization table'], correctAnswer: 1, explanation: 'The closure table stores every ancestor-descendant pair (including self-references). This enables O(1) subtree queries, ancestor queries, and depth calculations without recursive CTEs, at the cost of maintaining the closure table on changes.', codeSnippet: "CREATE TABLE categories (id SERIAL PRIMARY KEY, name TEXT);\n\nCREATE TABLE category_closure (\n  ancestor_id INTEGER REFERENCES categories(id),\n  descendant_id INTEGER REFERENCES categories(id),\n  depth INTEGER NOT NULL,\n  PRIMARY KEY (ancestor_id, descendant_id)\n);\n\n-- All descendants of category 5:\nSELECT c.* FROM categories c\nJOIN category_closure cc ON c.id = cc.descendant_id\nWHERE cc.ancestor_id = 5 AND cc.depth > 0;", tags: ['schema-design', 'hierarchy', 'closure-table'] },
  { id: 'pg-schema-design-l2-056', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you create a constraint that spans multiple tables?', options: ['Use a multi-table CHECK', 'PostgreSQL does not support cross-table CHECK constraints — use triggers, functions, or application-level validation instead', 'Use a FOREIGN KEY with CHECK', 'Use a cross-table ASSERT'], correctAnswer: 1, explanation: 'CHECK constraints can only reference the current row. For cross-table validation, use triggers (BEFORE INSERT/UPDATE), constraint triggers, or materialized views with constraints for eventual consistency.', codeSnippet: "-- Use a trigger for cross-table validation:\nCREATE FUNCTION check_budget() RETURNS TRIGGER AS $$\nBEGIN\n  IF (SELECT SUM(amount) FROM line_items WHERE order_id = NEW.order_id) > \n     (SELECT budget FROM departments d JOIN orders o ON o.dept_id = d.id WHERE o.id = NEW.order_id)\n  THEN\n    RAISE EXCEPTION 'Order exceeds department budget';\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['schema-design', 'constraints', 'cross-table', 'triggers'] },
  { id: 'pg-schema-design-l2-057', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Row Level Security', question: 'Can RLS policies be applied per operation type?', options: ['No, policies apply to all operations', 'Yes, you can create separate policies for SELECT, INSERT, UPDATE, and DELETE using the FOR clause', 'Only for SELECT and INSERT', 'Only with triggers'], correctAnswer: 1, explanation: 'RLS policies can target specific commands with FOR ALL, FOR SELECT, FOR INSERT, FOR UPDATE, or FOR DELETE. This allows different visibility rules for reads vs. writes.', codeSnippet: "-- Anyone can read public items\nCREATE POLICY read_public ON items FOR SELECT\n  USING (is_public OR owner_id = current_user_id());\n\n-- Only owners can update\nCREATE POLICY update_own ON items FOR UPDATE\n  USING (owner_id = current_user_id())\n  WITH CHECK (owner_id = current_user_id());\n\n-- Only owners can delete\nCREATE POLICY delete_own ON items FOR DELETE\n  USING (owner_id = current_user_id());", tags: ['schema-design', 'rls', 'per-operation'] },
  { id: 'pg-schema-design-l2-058', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Migration', question: 'What lock level does ALTER TABLE ADD COLUMN acquire?', options: ['No lock', 'AccessExclusiveLock — blocks all reads and writes, though the operation is instant for constant defaults in PG 11+', 'ShareLock', 'RowExclusiveLock'], correctAnswer: 1, explanation: 'ALTER TABLE acquires an AccessExclusiveLock, blocking all other operations. However, since PG 11, adding a column with a constant default is metadata-only and very fast, so the lock is held only briefly.', tags: ['schema-design', 'migration', 'locks', 'alter-table'] },
  { id: 'pg-schema-design-l2-059', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Data Types', question: 'What are the trade-offs of using JSONB columns vs. normalized tables?', options: ['JSONB is always better', 'JSONB offers schema flexibility and simpler queries for nested data but lacks foreign keys, has weaker type safety, and makes aggregate queries harder', 'Normalized tables are always better', 'No trade-offs, they are equivalent'], correctAnswer: 1, explanation: 'JSONB pros: flexible schema, no migrations for new fields, natural for nested data. Cons: no foreign keys, no NOT NULL on nested fields, weaker indexing, harder joins, no column-level statistics for the planner.', tags: ['schema-design', 'jsonb', 'normalization', 'trade-offs'] },
  { id: 'pg-schema-design-l2-060', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Naming', question: 'How should you name constraints for easier debugging?', options: ['Let PostgreSQL auto-name them', 'Use descriptive names following a pattern like tablename_columnname_constrainttype (e.g., orders_total_positive_check)', 'Use short codes', 'Naming is not important'], correctAnswer: 1, explanation: 'Descriptive constraint names make error messages immediately understandable. A consistent pattern like {table}_{columns}_{type} helps identify which constraint failed without querying the catalog.', codeSnippet: "CREATE TABLE orders (\n  id SERIAL CONSTRAINT orders_pkey PRIMARY KEY,\n  customer_id INTEGER\n    CONSTRAINT orders_customer_id_fkey REFERENCES customers(id),\n  total NUMERIC\n    CONSTRAINT orders_total_positive CHECK (total > 0),\n  email TEXT\n    CONSTRAINT orders_email_unique UNIQUE\n);", tags: ['schema-design', 'naming', 'constraints'] },
  { id: 'pg-schema-design-l2-061', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Foreign Keys', question: 'What is a deferred foreign key useful for?', options: ['Performance optimization', 'Allowing circular references or batch loads where referencing rows are inserted before referenced rows within the same transaction', 'Delaying index creation', 'Reducing lock contention'], correctAnswer: 1, explanation: 'Deferred FKs allow temporarily violating referential integrity during a transaction. The constraint is checked at COMMIT. This is essential for circular references (A references B, B references A) and bulk data loading.', codeSnippet: "CREATE TABLE departments (\n  id SERIAL PRIMARY KEY,\n  manager_id INTEGER REFERENCES employees(id)\n    DEFERRABLE INITIALLY DEFERRED\n);\nCREATE TABLE employees (\n  id SERIAL PRIMARY KEY,\n  department_id INTEGER REFERENCES departments(id)\n    DEFERRABLE INITIALLY DEFERRED\n);\n\nBEGIN;\nINSERT INTO departments (id, manager_id) VALUES (1, 1);\nINSERT INTO employees (id, department_id) VALUES (1, 1);\nCOMMIT;  -- FK checked here", tags: ['schema-design', 'foreign-key', 'deferred', 'circular'] },
  { id: 'pg-schema-design-l2-062', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Generated Columns', question: 'What limitations do generated columns have?', options: ['No limitations', 'Cannot reference other generated columns, subqueries, or functions that are not immutable; cannot be part of a partition key; cannot have their own DEFAULT', 'Only numeric expressions', 'Cannot be indexed'], correctAnswer: 1, explanation: 'Generated columns have several restrictions: expression must be immutable, cannot reference other generated columns, cannot use subqueries, cannot have DEFAULT, and cannot be used as partition key expressions.', tags: ['schema-design', 'generated-column', 'limitations'] },
  { id: 'pg-schema-design-l2-063', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Multi-tenancy', question: 'How does schema-per-tenant multi-tenancy work?', options: ['Each tenant gets a separate database', 'Each tenant has their own schema with identical table structures, and the application sets search_path per connection', 'Each tenant gets a separate column', 'Tenants share all schemas'], correctAnswer: 1, explanation: 'In schema-per-tenant, each tenant\'s data is in a separate schema (tenant_1.orders, tenant_2.orders). The application sets search_path to the tenant\'s schema. This provides good isolation with manageable overhead.', codeSnippet: "-- Create tenant schema:\nCREATE SCHEMA tenant_acme;\nCREATE TABLE tenant_acme.orders (LIKE public.orders_template INCLUDING ALL);\n\n-- Application sets search_path per request:\nSET search_path TO tenant_acme, public;\nSELECT * FROM orders;  -- queries tenant_acme.orders", tags: ['schema-design', 'multi-tenancy', 'schema-per-tenant'] },
  { id: 'pg-schema-design-l2-064', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'What is a constraint trigger?', options: ['A trigger on constraints', 'A trigger created with CREATE CONSTRAINT TRIGGER that can be deferred like a constraint and fires at commit time when deferred', 'A trigger that creates constraints', 'A CHECK constraint with a function'], correctAnswer: 1, explanation: 'Constraint triggers behave like regular triggers but support DEFERRABLE. When deferred, they fire at transaction commit time. This allows complex cross-table validations that are checked once at commit.', codeSnippet: "CREATE CONSTRAINT TRIGGER check_total\n  AFTER INSERT OR UPDATE ON order_items\n  DEFERRABLE INITIALLY DEFERRED\n  FOR EACH ROW\n  EXECUTE FUNCTION validate_order_total();", tags: ['schema-design', 'constraints', 'constraint-trigger'] },
  { id: 'pg-schema-design-l2-065', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Inheritance', question: 'How do you check which child table a row comes from in an inheritance query?', options: ['Use a type column', 'Use the tableoid system column which stores the OID of the table each row physically belongs to', 'Check the row version', 'Use pg_class lookup'], correctAnswer: 1, explanation: 'Every row has a hidden tableoid column containing the OID of the table it belongs to. You can cast it to regclass to get the table name, identifying which child table each row comes from.', codeSnippet: "SELECT tableoid::regclass AS source_table, *\nFROM vehicles;\n-- source_table | id | make | model | year\n-- vehicles     | 1  | BMW  | X5    | 2020\n-- cars         | 2  | Audi | A4    | 2022\n-- trucks       | 3  | Ford | F-150 | 2023", tags: ['schema-design', 'inheritance', 'tableoid'] },
  { id: 'pg-schema-design-l2-066', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'What is the performance overhead of having too many partitions?', options: ['No overhead', 'Query planning time increases with partition count; hundreds of partitions are fine but thousands can slow down planning and DDL operations', 'It only affects disk space', 'Partitions always improve performance'], correctAnswer: 1, explanation: 'Each partition adds overhead to query planning. With hundreds of partitions the planner is fast, but with thousands, planning time can dominate query execution. PostgreSQL 14+ improved this with partition pruning during planning.', tags: ['schema-design', 'partitioning', 'overhead', 'performance'] },
  { id: 'pg-schema-design-l2-067', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Migration', question: 'How do you safely rename a column in a live system?', options: ['Just use ALTER TABLE RENAME COLUMN', 'Deploy in phases: (1) add new column, (2) write to both, (3) backfill old to new, (4) switch reads, (5) drop old column', 'Rename is instant and safe', 'Use a view alias'], correctAnswer: 1, explanation: 'While ALTER TABLE RENAME COLUMN is instant, it breaks all queries referencing the old name. For zero-downtime, use a phased approach or create a view with the old name pointing to the new column as a compatibility layer.', tags: ['schema-design', 'migration', 'rename-column', 'zero-downtime'] },
  { id: 'pg-schema-design-l2-068', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Data Types', question: 'What is the citext extension?', options: ['A citation type', 'A case-insensitive text type that behaves like TEXT but compares and sorts case-insensitively without explicit LOWER() calls', 'A text compression type', 'A type for CI/CD data'], correctAnswer: 1, explanation: 'The citext extension provides a case-insensitive text type. Comparisons and unique constraints automatically ignore case. This is simpler than using LOWER() in every query and index.', codeSnippet: "CREATE EXTENSION citext;\n\nCREATE TABLE users (\n  id SERIAL PRIMARY KEY,\n  email citext UNIQUE NOT NULL\n);\n\nINSERT INTO users (email) VALUES ('Alice@Example.com');\nSELECT * FROM users WHERE email = 'alice@example.com';  -- found!", tags: ['schema-design', 'data-types', 'citext', 'case-insensitive'] },
  { id: 'pg-schema-design-l2-069', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you enforce that at least one row exists in a child table for each parent?', options: ['Use a NOT NULL foreign key', 'PostgreSQL cannot enforce minimum cardinality declaratively — use triggers or application logic to ensure at least one child row', 'Use a CHECK constraint', 'Use a REQUIRED CHILD constraint'], correctAnswer: 1, explanation: 'SQL constraints cannot enforce minimum cardinality (at least N children). Foreign keys ensure referential integrity but not existence. Use AFTER triggers on the parent table or application logic to validate.', tags: ['schema-design', 'constraints', 'cardinality'] },
  { id: 'pg-schema-design-l2-070', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Schemas', question: 'How do you move a table to a different schema?', options: ['Copy and delete', 'ALTER TABLE table_name SET SCHEMA new_schema', 'MOVE TABLE to schema', 'TRANSFER TABLE to schema'], correctAnswer: 1, explanation: 'ALTER TABLE ... SET SCHEMA moves a table to a different schema. Foreign keys, indexes, and triggers move with the table. Views and functions referencing the table by the old schema-qualified name must be updated.', codeSnippet: "ALTER TABLE public.archived_orders SET SCHEMA archive;\n-- Now accessed as archive.archived_orders", tags: ['schema-design', 'schemas', 'move-table'] },
  { id: 'pg-schema-design-l2-071', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'Can foreign keys reference a partitioned table?', options: ['Yes, always supported', 'Yes, since PostgreSQL 12 — foreign keys can reference partitioned tables, and the constraint is enforced across all partitions', 'No, never supported', 'Only with special extensions'], correctAnswer: 1, explanation: 'PostgreSQL 12 added support for foreign keys referencing partitioned tables. The referenced column must be part of the partition key. Foreign keys from partitioned tables to other tables have been supported since PG 11.', tags: ['schema-design', 'partitioning', 'foreign-key'] },
  { id: 'pg-schema-design-l2-072', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Generated Columns', question: 'Can you use a generated column to implement a full-text search vector?', options: ['Yes, use a generated column with to_tsvector()', 'No, to_tsvector() is not immutable — use a trigger to maintain a tsvector column instead', 'Only with GIN indexes', 'Only in PostgreSQL 16+'], correctAnswer: 1, explanation: 'to_tsvector() depends on the text search configuration (a session setting), making it not immutable. Generated columns require immutable expressions. Use a BEFORE INSERT/UPDATE trigger to maintain the tsvector column instead.', codeSnippet: "-- Cannot use generated column (not immutable)\n-- Instead, use a trigger:\nCREATE TABLE articles (\n  id SERIAL PRIMARY KEY,\n  title TEXT, body TEXT,\n  search_vector TSVECTOR\n);\n\nCREATE FUNCTION update_search_vector() RETURNS TRIGGER AS $$\nBEGIN\n  NEW.search_vector := to_tsvector('english', NEW.title || ' ' || NEW.body);\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_search BEFORE INSERT OR UPDATE\n  ON articles FOR EACH ROW EXECUTE FUNCTION update_search_vector();", tags: ['schema-design', 'generated-column', 'full-text-search', 'trigger'] },
  { id: 'pg-schema-design-l2-073', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Migration', question: 'What is the safest way to change a column type on a large table?', options: ['ALTER TABLE ALTER COLUMN TYPE directly', 'Create a new column, backfill in batches, switch over, then drop the old column — avoids long-running table locks', 'Drop and recreate the table', 'Use CAST in a view'], correctAnswer: 1, explanation: 'ALTER COLUMN TYPE rewrites the entire table with an AccessExclusiveLock. For large tables, the phased approach avoids downtime: add new column, backfill, switch application, drop old column.', codeSnippet: "-- Step 1: Add new column\nALTER TABLE orders ADD COLUMN total_new NUMERIC(12,2);\n\n-- Step 2: Backfill in batches\nUPDATE orders SET total_new = total::numeric(12,2)\nWHERE id BETWEEN 1 AND 10000;\n-- ... repeat for batches\n\n-- Step 3: Switch (in a transaction)\nBEGIN;\nALTER TABLE orders RENAME COLUMN total TO total_old;\nALTER TABLE orders RENAME COLUMN total_new TO total;\nCOMMIT;\n\n-- Step 4: Drop old column later\nALTER TABLE orders DROP COLUMN total_old;", tags: ['schema-design', 'migration', 'column-type', 'zero-downtime'] },
  { id: 'pg-schema-design-l2-074', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you create an expression-based unique constraint?', options: ['Use UNIQUE with an expression', 'Create a unique index on an expression — PostgreSQL does not support expressions in UNIQUE constraints directly', 'Use UNIQUE EXPRESSION', 'Use CHECK with UNIQUE'], correctAnswer: 1, explanation: 'While UNIQUE constraints only accept column names, you can create a unique index on an expression to achieve the same effect. This is commonly used for case-insensitive uniqueness.', codeSnippet: "-- Case-insensitive unique email:\nCREATE UNIQUE INDEX idx_users_email_lower\n  ON users (LOWER(email));\n\n-- Unique on truncated timestamp (one per day):\nCREATE UNIQUE INDEX idx_daily_report\n  ON reports (user_id, date_trunc('day', created_at));", tags: ['schema-design', 'unique', 'expression-index'] },
  { id: 'pg-schema-design-l2-075', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Temporal Design', question: 'What is a slowly changing dimension (SCD) in schema design?', options: ['A dimension that loads slowly', 'A design pattern for tracking how dimension attributes change over time, with types ranging from overwrite (Type 1) to versioned rows (Type 2)', 'A table with a slow query', 'A temporary dimension'], correctAnswer: 1, explanation: 'SCD Type 1 overwrites old values (no history). Type 2 adds versioned rows with valid_from/valid_to dates. Type 3 adds columns for current and previous values. Type 2 is most common for full history tracking.', codeSnippet: "-- SCD Type 2: versioned rows\nCREATE TABLE product_prices (\n  product_id INTEGER NOT NULL,\n  price NUMERIC NOT NULL,\n  valid_from DATE NOT NULL,\n  valid_to DATE,  -- NULL = current\n  is_current BOOLEAN DEFAULT true,\n  UNIQUE (product_id, valid_from)\n);", tags: ['schema-design', 'scd', 'temporal', 'data-warehouse'] },
  { id: 'pg-schema-design-l2-076', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Data Types', question: 'When should you use the ltree extension for hierarchical data?', options: ['For any tree structure', 'When you need efficient queries on hierarchical label paths with ancestor/descendant matching and GiST index support', 'Only for file systems', 'Never, use recursive CTEs instead'], correctAnswer: 1, explanation: 'The ltree extension provides a data type for hierarchical labels (e.g., "Top.Countries.Europe.Germany"). It supports operators for ancestry (@>), descendancy (<@), and pattern matching (~) with GiST indexing.', codeSnippet: "CREATE EXTENSION ltree;\n\nCREATE TABLE categories (\n  id SERIAL PRIMARY KEY,\n  name TEXT NOT NULL,\n  path ltree NOT NULL\n);\nCREATE INDEX ON categories USING GIST (path);\n\n-- All descendants of 'Top.Electronics':\nSELECT * FROM categories WHERE path <@ 'Top.Electronics';\n-- All ancestors of a leaf:\nSELECT * FROM categories WHERE path @> 'Top.Electronics.Phones.Apple';", tags: ['schema-design', 'ltree', 'hierarchy', 'extension'] },
  { id: 'pg-schema-design-l2-077', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Materialized Views', question: 'When should you use a materialized view vs. a regular table with triggers?', options: ['Always use materialized views', 'Materialized views for periodic batch refresh; trigger-maintained tables for real-time updates and when you need DML on the result', 'They are interchangeable', 'Never use materialized views'], correctAnswer: 1, explanation: 'Materialized views are simpler but only support full refresh (or concurrent refresh). For real-time denormalized data, a regular table maintained by triggers provides immediate consistency without refresh overhead.', tags: ['schema-design', 'materialized-view', 'triggers', 'comparison'] },
  { id: 'pg-schema-design-l2-078', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you add a unique constraint concurrently (without blocking)?', options: ['ALTER TABLE ADD CONSTRAINT CONCURRENTLY', 'Create a unique index concurrently first, then add the constraint using the existing index', 'Use ADD CONSTRAINT NOT VALID', 'Unique constraints always block'], correctAnswer: 1, explanation: 'CREATE UNIQUE INDEX CONCURRENTLY builds the index without blocking writes. Then ALTER TABLE ADD CONSTRAINT ... USING INDEX attaches it as a constraint. This avoids the AccessExclusiveLock during index building.', codeSnippet: "-- Step 1: Build index without blocking (can take a while)\nCREATE UNIQUE INDEX CONCURRENTLY idx_users_email\n  ON users (email);\n\n-- Step 2: Attach as constraint (brief lock)\nALTER TABLE users ADD CONSTRAINT users_email_unique\n  UNIQUE USING INDEX idx_users_email;", tags: ['schema-design', 'unique', 'concurrent', 'zero-downtime'] },
  { id: 'pg-schema-design-l2-079', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Data Types', question: 'What is the purpose of the pg_trgm extension for schema design?', options: ['Trigonometric calculations', 'Provides trigram-based similarity search and GiST/GIN index support for LIKE, ILIKE, and similarity queries on text columns', 'Data triangulation', 'Three-way merge support'], correctAnswer: 1, explanation: 'pg_trgm breaks text into trigrams (3-character sequences) and provides operators for similarity matching. GiST/GIN indexes on trgm support efficient LIKE/ILIKE patterns and fuzzy string matching.', codeSnippet: "CREATE EXTENSION pg_trgm;\n\nCREATE INDEX ON users USING GIN (name gin_trgm_ops);\n\n-- Efficient LIKE with index:\nSELECT * FROM users WHERE name LIKE '%smith%';\n\n-- Similarity search:\nSELECT name, similarity(name, 'Jon Smith') AS sim\nFROM users WHERE name % 'Jon Smith'\nORDER BY sim DESC;", tags: ['schema-design', 'pg-trgm', 'similarity', 'extension'] },
  { id: 'pg-schema-design-l2-080', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Normalization', question: 'What is Fifth Normal Form (5NF)?', options: ['Having five tables', 'Being in 4NF with no join dependencies that are not implied by candidate keys — every join dependency is a consequence of candidate keys', 'A theoretical form never used', 'Requiring five indexes'], correctAnswer: 1, explanation: '5NF (also called PJNF — Project-Join Normal Form) eliminates all remaining redundancy from join dependencies. A table is in 5NF if it cannot be decomposed into smaller tables and joined back without loss.', tags: ['schema-design', 'normalization', '5nf'] },
  { id: 'pg-schema-design-l2-081', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'How do you handle a unique constraint across all partitions?', options: ['Standard UNIQUE works across partitions', 'The unique constraint must include the partition key columns — a globally unique constraint without the partition key is not supported', 'Use a separate unique index', 'Use a trigger for uniqueness'], correctAnswer: 1, explanation: 'PostgreSQL requires unique indexes on partitioned tables to include all partition key columns. A globally unique constraint without the partition key requires workarounds like a separate lookup table with a unique constraint.', codeSnippet: "-- This works (includes partition key):\nCREATE UNIQUE INDEX ON measurements (id, recorded_at);\n\n-- This does NOT work:\n-- CREATE UNIQUE INDEX ON measurements (id);\n-- ERROR: unique constraint must include all partition key columns\n\n-- Workaround for global uniqueness:\nCREATE TABLE measurement_ids (id BIGSERIAL PRIMARY KEY);\n-- FK from measurements to measurement_ids", tags: ['schema-design', 'partitioning', 'unique', 'limitation'] },
  { id: 'pg-schema-design-l2-082', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Audit Trail', question: 'How do you track which user made a change in an audit trigger?', options: ['PostgreSQL always logs users', 'Use current_user for the database role, or set a session variable (current_setting) with the application-level user ID', 'Check pg_stat_activity', 'Use the connection log'], correctAnswer: 1, explanation: 'current_user returns the database role. For application users connecting through a shared role, set a session variable (e.g., SET app.user_id = 42) at connection time, then read it in the trigger with current_setting().', codeSnippet: "-- Application sets user context per request:\nSET LOCAL app.user_id = '42';\n\n-- Trigger reads it:\nCREATE FUNCTION audit_trigger() RETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO audit_log (table_name, operation, changed_by, row_id)\n  VALUES (TG_TABLE_NAME, TG_OP,\n    current_setting('app.user_id', true), NEW.id);\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['schema-design', 'audit-trail', 'user-tracking'] },
  { id: 'pg-schema-design-l2-083', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Views', question: 'What is a recursive view?', options: ['A view that references itself', 'A view defined using CREATE RECURSIVE VIEW which is syntactic sugar for a view containing a recursive CTE', 'A view that updates automatically', 'A view with a loop'], correctAnswer: 1, explanation: 'CREATE RECURSIVE VIEW is shorthand for a view whose body is a UNION ALL recursive CTE. It simplifies writing views for hierarchical data traversal.', codeSnippet: "CREATE RECURSIVE VIEW org_tree (id, name, manager_id, depth) AS\n  SELECT id, name, manager_id, 0\n  FROM employees WHERE manager_id IS NULL\n  UNION ALL\n  SELECT e.id, e.name, e.manager_id, t.depth + 1\n  FROM employees e JOIN org_tree t ON e.manager_id = t.id;", tags: ['schema-design', 'views', 'recursive'] },
  { id: 'pg-schema-design-l2-084', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Row Level Security', question: 'What is the PERMISSIVE vs RESTRICTIVE policy distinction?', options: ['They are identical', 'PERMISSIVE policies are ORed together (any matching policy grants access); RESTRICTIVE policies are ANDed (all must pass)', 'PERMISSIVE is less secure', 'RESTRICTIVE blocks all access'], correctAnswer: 1, explanation: 'Multiple PERMISSIVE policies are combined with OR: if any policy passes, access is granted. RESTRICTIVE policies (PG 10+) are combined with AND: all must pass. At least one PERMISSIVE policy must also pass.', codeSnippet: "-- PERMISSIVE: user can see own docs OR public docs (OR)\nCREATE POLICY see_own ON docs AS PERMISSIVE FOR SELECT\n  USING (owner_id = current_user_id());\nCREATE POLICY see_public ON docs AS PERMISSIVE FOR SELECT\n  USING (is_public = true);\n\n-- RESTRICTIVE: must also not be archived (AND)\nCREATE POLICY not_archived ON docs AS RESTRICTIVE FOR SELECT\n  USING (archived_at IS NULL);", tags: ['schema-design', 'rls', 'permissive-restrictive'] },
  { id: 'pg-schema-design-l2-085', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Migration', question: 'What is the expand-and-contract pattern for schema migrations?', options: ['A backup strategy', 'A two-phase migration: expand (add new structures while keeping old), then contract (remove old structures after all clients migrate)', 'A compression technique', 'A testing pattern'], correctAnswer: 1, explanation: 'Expand phase: add new columns/tables without removing old ones (backward compatible). Contract phase: after all application instances use the new schema, remove deprecated structures. This ensures zero-downtime deployments.', tags: ['schema-design', 'migration', 'expand-contract', 'zero-downtime'] },
  { id: 'pg-schema-design-l2-086', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you add a foreign key constraint concurrently?', options: ['ALTER TABLE ADD CONSTRAINT ... CONCURRENTLY', 'Add the foreign key with NOT VALID (brief lock), then VALIDATE CONSTRAINT separately (weaker lock, allows concurrent access)', 'Foreign keys always block', 'Use CREATE INDEX CONCURRENTLY'], correctAnswer: 1, explanation: 'ADD CONSTRAINT ... NOT VALID acquires a ShareRowExclusiveLock briefly without scanning data. VALIDATE CONSTRAINT later acquires a ShareUpdateExclusiveLock (allows reads/writes) while scanning. This minimizes blocking.', codeSnippet: "-- Brief lock, no scan:\nALTER TABLE orders ADD CONSTRAINT fk_customer\n  FOREIGN KEY (customer_id) REFERENCES customers(id)\n  NOT VALID;\n\n-- Longer scan, weaker lock (reads/writes OK):\nALTER TABLE orders VALIDATE CONSTRAINT fk_customer;", tags: ['schema-design', 'foreign-key', 'concurrent', 'zero-downtime'] },
  { id: 'pg-schema-design-l2-087', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Data Types', question: 'What are the trade-offs between UUID v4 and SERIAL for primary keys?', options: ['UUID is always better', 'UUID provides global uniqueness and non-guessability but has larger storage (16 bytes), worse index locality, and slower INSERT due to random distribution', 'SERIAL is always better', 'No trade-offs, they are equivalent'], correctAnswer: 1, explanation: 'UUID v4: globally unique, non-sequential, 16 bytes, random B-tree inserts cause page splits. SERIAL: sequential, 4/8 bytes, append-only B-tree inserts, but sequential and guessable. UUID v7 mitigates locality issues with time-ordered UUIDs.', tags: ['schema-design', 'uuid', 'serial', 'primary-key', 'trade-offs'] },
  { id: 'pg-schema-design-l2-088', language: 'postgresql', level: 'level2', category: 'Schema Design', subcategory: 'Partitioning', question: 'How do you manage partition maintenance automation?', options: ['Manual creation only', 'Use pg_partman extension for automatic partition creation, retention, and maintenance, or write custom scripts using pg_cron', 'PostgreSQL auto-creates partitions', 'Use replication for maintenance'], correctAnswer: 1, explanation: 'pg_partman automates creating future partitions, dropping/detaching old ones, and managing defaults. For simpler needs, a pg_cron job running DDL to create monthly/daily partitions works well.', codeSnippet: "-- Using pg_partman:\nCREATE EXTENSION pg_partman;\n\nSELECT create_parent(\n  p_parent_table := 'public.measurements',\n  p_control := 'recorded_at',\n  p_type := 'native',\n  p_interval := 'monthly',\n  p_premake := 3  -- create 3 future partitions\n);\n\n-- Schedule maintenance:\nSELECT run_maintenance();", tags: ['schema-design', 'partitioning', 'pg-partman', 'automation'] },
];

export default questions;
